// Nimmt das vom Browser gesendete Paket entgegen und bereitet eine
// JSON-Datei für Google Drive vor.
// Erwartet entweder { source, events: [...] } (Batches) oder
// { source, type: 'report', report: {...} } (aggregierter Bericht).
const body = $input.first().json.body ?? $input.first().json;
const isReport = !!(body && body.type === 'report' && body.report);
const kind = isReport ? 'report' : 'events';
const data = isReport ? body.report : (body.events ?? body);
const now = new Date();
const stamp = now.toISOString().replace(/[:.]/g, '-');
return [{
  json: {
    filename: `rhetorix-${kind}-${stamp}.json`,
    content: JSON.stringify(data, null, 2),
    kind,
    count: Array.isArray(body && body.events) ? body.events.length : 1,
    receivedAt: now.toISOString()
  }
}];
